      "meaning": "redentor, aquele que resgata como parente",
      "note": "gōʾēl carrega a ideia de redentor, aquele que resgata como parente. O mesmo instrumento que Deus usou para julgar Judá — a Babilônia — agora se torna, ela mesma, alvo do julgamento de Deus, provando que nenhuma potência humana, por mais usada por Deus, está isenta de prestar contas. Lida de perto, essa palavra deixa de ser apenas um detalhe do texto e se torna um convite para olhar com mais verdade para aquilo que o coração tenta esconder ou controlar."
